<style>
  * { box-sizing: border-box; }
  body { margin: 0; font-family: "Sohne", -apple-system, "Pretendard", "Helvetica Neue", sans-serif; color: var(--text-primary); background: var(--bg-base); }
  .stripe-demo { min-height: 100vh; overflow: hidden; background: var(--bg-base); }
  .stripe-nav { height: 72px; padding: 0 24px; display: flex; align-items: center; gap: 34px; position: relative; z-index: 5; max-width: 1200px; margin: 0 auto; }
  .stripe-logo { color: var(--color-primary-500); font-size: 25px; line-height: 1; font-weight: 700; letter-spacing: -.05em; }
  .stripe-links { display: flex; gap: 26px; margin-left: 12px; }
  .stripe-links a { color: var(--text-primary); text-decoration: none; font-size: 14px; font-weight: 600; }
  .stripe-nav .btn { margin-left: auto; height: 34px; padding: 8px 15px; font-size: 13px; }
  .stripe-hero { min-height: 600px; padding: 72px 24px 88px; position: relative; }
  .stripe-ribbon { position: absolute; z-index: 0; width: 820px; height: 280px; right: -180px; top: -110px; transform: rotate(-11deg); border-radius: 120px; background: linear-gradient(118deg,#E6A83E 0%,#E96768 24%,#9557D6 51%,#635BFF 73%,#00B8E0 100%); box-shadow: 0 42px 80px rgba(0,0,0,.32); }
  .stripe-ribbon::after { content: ""; position: absolute; inset: 34px 80px; border-radius: inherit; background: linear-gradient(110deg,rgba(255,255,255,.20),transparent 45%,rgba(3,12,22,.28)); filter: blur(16px); }
  .stripe-hero-inner { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: minmax(0,1.02fr) minmax(420px,.98fr); gap: 72px; align-items: center; position: relative; z-index: 1; }
  .stripe-eyebrow { display: inline-flex; align-items: center; gap: 8px; color: var(--color-primary-700); font-size: 13px; font-weight: 700; margin-bottom: 22px; }
  .stripe-eyebrow::before { content: ""; width: 24px; height: 2px; background: var(--color-primary-500); border-radius: 2px; }
  .stripe-hero h1 { max-width: 650px; font-size: clamp(48px,6vw,76px); font-weight: 650; line-height: .98; letter-spacing: -.055em; margin: 0 0 28px; color: var(--text-primary); }
  .stripe-hero h1 span { color: var(--color-primary-500); }
  .stripe-hero-copy { max-width: 540px; color: var(--text-secondary); font-size: 19px; line-height: 1.55; margin: 0 0 32px; }
  .stripe-actions { display: flex; gap: 12px; align-items: center; }
  .stripe-actions .btn-ghost { color: var(--text-primary); }
  .stripe-console { background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: var(--radius-xl); box-shadow: var(--shadow-xl); overflow: hidden; transform: rotate(1.2deg); }
  .console-bar { height: 46px; padding: 0 18px; display: flex; align-items: center; border-bottom: 1px solid var(--border-default); background: var(--bg-subtle); color: var(--text-tertiary); font-size: 12px; }
  .console-dot { width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }
  .console-title { margin-left: auto; color: var(--text-secondary); font-weight: 600; }
  .console-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--border-subtle); }
  .metric { background: var(--bg-elevated); padding: 20px; }
  .metric-label { color: var(--text-tertiary); font-size: 12px; margin-bottom: 6px; }
  .metric-value { font-size: 27px; font-weight: 650; letter-spacing: -.03em; }
  .metric-change { color: var(--color-success-fg); font-size: 11px; font-weight: 600; }
  .console-code { padding: 22px; font: 13px/1.65 "Sohne Mono", ui-monospace, SFMono-Regular, Consolas, monospace; color: var(--text-secondary); background: var(--bg-subtle); }
  .console-code .method { color: var(--color-error-fg); }
  .console-code .path { color: var(--color-primary-700); }
  .console-code .value { color: var(--color-success-fg); }
  .console-result { padding: 12px 22px; border-top: 1px solid var(--border-default); display: flex; align-items: center; color: var(--text-secondary); font-size: 12px; }
  .console-result strong { color: var(--color-success-fg); margin-left: auto; }
  .stripe-features { max-width: 1200px; margin: 0 auto 96px; padding: 0 24px; display: grid; grid-template-columns: repeat(3,1fr); gap: 22px; }
  .stripe-feature { min-height: 228px; background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: var(--radius-lg); padding: 28px; box-shadow: var(--shadow-sm); position: relative; overflow: hidden; transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base) var(--ease-out); }
  .stripe-feature:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
  .feature-icon { width: 42px; height: 42px; border-radius: 10px; display: grid; place-items: center; color: #fff; background: linear-gradient(135deg,var(--color-primary-400),var(--color-primary-600)); box-shadow: 0 8px 18px rgba(0,0,0,.28); }
  .feature-icon svg { width: 22px; height: 22px; }
  .stripe-feature h3 { margin: 24px 0 8px; font-size: 20px; letter-spacing: -.02em; }
  .stripe-feature p { margin: 0; color: var(--text-secondary); font-size: 14px; line-height: 1.55; }
  .stripe-feature a { display: inline-block; margin-top: 18px; color: var(--color-primary-700); font-size: 13px; font-weight: 650; }
  @media (max-width: 860px) {
    .stripe-links { display: none; }
    .stripe-hero { padding-top: 48px; }
    .stripe-hero-inner { grid-template-columns: 1fr; }
    .stripe-console { transform: none; }
    .stripe-features { grid-template-columns: 1fr; }
  }
</style>

